import pathlib,json,statistics,collections,hashlib
p=pathlib.Path('/home/vrondelli/projects/cyberAlchemy-v2/implementation/agent-reasoning-engine/benchmarks/glm-episodes-v1/evidence/contract-loop-2026-09-07/iteration-01')
r=json.loads((p/'result.json').read_text());m=json.loads((p/'manifest.json').read_text())
for s in m['sources']:assert hashlib.sha256(pathlib.Path(s['path']).read_bytes()).hexdigest()==s['sha256']
trials=[]
for trial in r['trials']:
 report=trial['report'];a=report['arms'][0];complete=json.loads((p/f"trial-{trial['index']:02d}/arm-0/completed.json").read_text())
 passed=a.get('verified_repair') is True;continuity=a.get('continuity',{}).get('passed') is True
 reasons=a.get('reasons',[])
 oracle=complete.get('verification',{});oracle=oracle if isinstance(oracle,dict) else {}
 if not passed and not reasons:reasons=oracle.get('reason_codes',[]) or ['no-verified-repair']
 headroom=[d['soft_headroom_tokens'] for d in complete.get('dispatch_headroom',[])]
 assert all(v>0 for v in headroom)
 trials.append({'index':trial['index'],'repetition':trial['repetition'],'episode':trial['episode'],'soft_limit':trial['soft_limit'],'policy':trial['policy'],'repair':passed,'continuity':continuity,'joint_pass':passed and continuity,'reasons':reasons,'model_attempts':report['totals']['model_attempts'],'tokenizer_attempts':report['totals']['tokenizer_attempts'],'input_tokens':report['totals']['input_tokens'],'output_tokens':report['totals']['output_tokens'],'elapsed_ms':a['elapsed_ms'],'minimum_soft_headroom':min(headroom) if headroom else None,'recycles':complete['recycles'],'repeated_successful_file_reads':a['read_activity']['repeated_successful_file_reads']})
def stats(items):
 known=lambda k:[x[k] for x in items if isinstance(x[k],(int,float))]
 return {'trials':len(items),'recycling_exercised':sum(t['recycles']>0 for t in items),'repairs':sum(t['repair'] for t in items),'continuity_passes':sum(t['continuity'] for t in items),'joint_passes':sum(t['joint_pass'] for t in items),'model_attempts':sum(known('model_attempts')),'tokenizer_attempts':sum(known('tokenizer_attempts')),'known_input_tokens':sum(known('input_tokens')),'input_usage_unknown_trials':len(items)-len(known('input_tokens')),'known_output_tokens':sum(known('output_tokens')),'output_usage_unknown_trials':len(items)-len(known('output_tokens')),'median_elapsed_ms':statistics.median(known('elapsed_ms')),'min_elapsed_ms':min(known('elapsed_ms')),'max_elapsed_ms':max(known('elapsed_ms')),'mean_model_attempts':statistics.mean(known('model_attempts'))}
groups=[]
for limit in [8000,10000,12000]:
 for policy in ['clear-v1','recent-observations-v2']:
  items=[t for t in trials if t['soft_limit']==limit and t['policy']==policy]
  if items:groups.append({'soft_limit':limit,'policy':policy,**stats(items)})
policies=[{'policy':policy,**stats([t for t in trials if t['policy']==policy])} for policy in ['clear-v1','recent-observations-v2'] if any(t['policy']==policy for t in trials)]
summary={'authority_effect':'none','status':r['status'],'planned':6,'completed':len(trials),'sources_unchanged':True,'totals':stats(trials),'groups':groups,'policies':policies,'trials':trials,'failure_counts':dict(collections.Counter(reason for t in trials for reason in t['reasons'])),'open_questions_ref':'README.md#open-questions'}
(p/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
lines=['# Compact contract iteration 01','',f"Completed {len(trials)} of 6 predeclared trials. Joint repair-and-continuity passes: {sum(t['joint_pass'] for t in trials)}/{len(trials)}. No tuning or failure replacement occurred.",'','| Soft limit | Policy | Repair | Recycling exercised | Continuity | Both | Mean model calls | Median time |','| ---: | --- | ---: | ---: | ---: | ---: | ---: | ---: |']
for g in groups:lines.append(f"| {g['soft_limit']} | {g['policy']} | {g['repairs']}/{g['trials']} | {g['recycling_exercised']}/{g['trials']} | {g['continuity_passes']}/{g['trials']} | {g['joint_passes']}/{g['trials']} | {g['mean_model_attempts']:.1f} | {g['median_elapsed_ms']/1000:.1f}s |")
lines+=['','Repair requires all eight oracle checks. Continuity separately requires the prescribed reads and delivery, actual recycling, and archive recovery after recycling. A repair without recycling does not exercise continuity. Three repetitions per group cannot establish reliable superiority.','','## All outcomes','','| Trial | Rep | Soft limit | Policy | Repair | Recycles | Continuity | Model/tokenizer calls | Outcome |','| --- | ---: | ---: | --- | --- | ---: | --- | --- | --- |']
for t in trials:lines.append(f"| [trial-{t['index']:02d}](trial-{t['index']:02d}/checked-report.json) | {t['repetition']} | {t['soft_limit']} | {t['policy']} | {t['repair']} | {t['recycles']} | {t['continuity']} | {t['model_attempts']}/{t['tokenizer_attempts']} | {', '.join(t['reasons']) or ('Joint pass' if t['joint_pass'] else 'Continuity not demonstrated')} |")
t=summary['totals']
lines+=['','## Usage and validation','',f"Recorded attempts: {t['model_attempts']} model, {t['tokenizer_attempts']} tokenizer. Known input/output tokens: {t['known_input_tokens']}/{t['known_output_tokens']}; unknown-usage trials: {t['input_usage_unknown_trials']}/{t['output_usage_unknown_trials']}. Median arm time {t['median_elapsed_ms']/1000:.1f}s; range {t['min_elapsed_ms']/1000:.1f}–{t['max_elapsed_ms']/1000:.1f}s.",'','All 362 local tests passed before freezing ([log](prior-tests.tap)). The [plan](PLAN.md), [manifest](manifest.json) and [driver](driver.py) record the predeclared schedule. Source hashes matched before and after each arm and at aggregation. Runtime/prompt/oracle remained frozen; task manifests matched across limits and repetitions. Each arm allowed 12 model/24 tokenizer calls and 580 seconds. Aggregate caps were 72/144. No automatic retry or failure replacement occurred.','','All actual dispatches had positive headroom under their assigned soft limit, including output reserve 2048 and token margin 256. Hard limit remained 16384. This verifies ARE request admission and observed recycling, and cannot establish whether the provider internally compacted a request. Defaults remain unchanged.','','Checked reports verify recorded integrity/policy/accounting bindings, not cryptographic authenticity or a fresh oracle replay. Repairs were evaluated in isolated copies. Visible exports exclude raw message history and provider reasoning. Complete private report inputs remain under /tmp/are-glm-contract-loop-01; exported subsets are not complete report inputs. Authority effect none.','','## Open Questions','','- Do observed differences persist with more repetitions and additional tasks?','- How can archive recovery and repair improve without using the evaluation samples for tuning?','- Which failures are caused by model behavior versus provider availability?','- What evidence would justify changing the default soft limit or retention policy?','']
(p/'README.md').write_text('\n'.join(lines))
print(json.dumps({'totals':summary['totals'],'groups':groups,'failure_counts':summary['failure_counts']},indent=2))
